css:
.dba-cohort {
  --dba-cohort-bg: oklch(0.978 0.005 220);
  --dba-cohort-ink: oklch(0.25 0.03 235);
  --dba-cohort-hi: oklch(0.44 0.1 200);
  --dba-cohort-pin: oklch(0.66 0.17 32);
  --dba-cohort-lo: color-mix(in oklch, var(--dba-cohort-hi) 7%, var(--dba-cohort-bg));
  --dba-cohort-card: color-mix(in oklch, var(--dba-cohort-bg) 40%, white);
  --dba-cohort-line: color-mix(in oklch, var(--dba-cohort-ink) 10%, transparent);
  --dba-cohort-soft: color-mix(in oklch, var(--dba-cohort-ink) 4.5%, transparent);
  --dba-cohort-mute: color-mix(in oklch, var(--dba-cohort-ink) 60%, var(--dba-cohort-bg));
  --dba-cohort-faint: color-mix(in oklch, var(--dba-cohort-ink) 38%, var(--dba-cohort-bg));
  --dba-cohort-p1: var(--dba-cohort-pin);
  --dba-cohort-p2: oklch(0.72 0.14 80);
  --dba-cohort-p3: oklch(0.48 0.13 262);
  --dba-cohort-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-cohort-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-cohort-out: cubic-bezier(.22, 1, .36, 1);
  width: 100%;
  height: var(--dba-cohort-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dba-cohort-bg); color: var(--dba-cohort-ink);
  font: 13px/1.45 var(--dba-cohort-sans);
  accent-color: var(--dba-cohort-hi);
  scrollbar-color: color-mix(in oklch, var(--dba-cohort-ink) 20%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dba-cohort-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dba-cohort-hi); outline-offset: 2px; }
  & .ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
}
.dba-cohort__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dba-cohort__shell { height: 100%; display: grid; grid-template-columns: 220px minmax(0, 1fr); }
.dba-cohort__side {
  display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; overflow: auto; scrollbar-width: thin;
  border-right: 1px solid var(--dba-cohort-line);
}
.dba-cohort__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 8px 18px; font-weight: 720; font-size: 15px; letter-spacing: -.02em; line-height: 1.15;
  & small { display: block; font-size: 11.5px; font-weight: 500; color: var(--dba-cohort-mute); letter-spacing: 0; }
  & i {
    width: 30px; height: 30px; border-radius: 9px; flex: none;
    background:
      conic-gradient(from 210deg, var(--dba-cohort-hi) 0 25%, color-mix(in oklch, var(--dba-cohort-hi) 60%, white) 0 50%, color-mix(in oklch, var(--dba-cohort-hi) 30%, white) 0 75%, var(--dba-cohort-pin) 0);
    mask: radial-gradient(circle at 50% 50%, transparent 4.5px, #000 5px);
  }
}
.dba-cohort__nav { display: grid; gap: 2px; }
.dba-cohort__item {
  position: relative; display: flex; align-items: center; gap: 11px; padding: 9px 10px; border-radius: 10px; text-align: left; color: var(--dba-cohort-mute);
  transition: background-color .2s, color .2s;
  & small { display: block; font-size: 11px; color: var(--dba-cohort-faint); }
  &:hover { background: var(--dba-cohort-soft); color: var(--dba-cohort-ink); }
  &[aria-current="page"] { background: color-mix(in oklch, var(--dba-cohort-hi) 11%, transparent); color: var(--dba-cohort-ink); font-weight: 620; }
  &[aria-current="page"] .ic { color: var(--dba-cohort-hi); }
}
.dba-cohort__note {
  margin-top: auto; padding: 12px 10px; border-radius: 12px; font-size: 12px; color: var(--dba-cohort-mute); text-wrap: pretty;
  background: color-mix(in oklch, var(--dba-cohort-pin) 9%, transparent);
  & b { color: color-mix(in oklch, var(--dba-cohort-pin) 70%, black); font-weight: 650; }
}
.dba-cohort__main {
  min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 18px 20px;
  display: grid; gap: 12px;
  grid-template-columns: minmax(0, 1.75fr) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "head head" "kpis kpis" "heat curve";
}
.dba-cohort__head { grid-area: head; display: flex; align-items: center; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; }
.dba-cohort__title {
  min-width: 0;
  & h2 { font-size: clamp(19px, 2.2cqi, 25px); font-weight: 740; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; color: var(--dba-cohort-ink); }
  & p { color: var(--dba-cohort-mute); margin-top: 3px; text-wrap: pretty; }
}
.dba-cohort__ctrls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.dba-cohort__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dba-cohort-soft); box-shadow: inset 0 0 0 1px var(--dba-cohort-line);
  & button { min-width: 32px; padding: 6px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dba-cohort-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dba-cohort-ink); }
  & button[aria-checked="true"] { background: var(--dba-cohort-card); color: var(--dba-cohort-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dba-cohort-ink) 20%, transparent); }
}
.dba-cohort__select {
  position: relative; display: inline-flex; align-items: center;
  & select {
    appearance: none; font: 600 12.5px var(--dba-cohort-sans); color: var(--dba-cohort-ink); padding: 8px 32px 8px 12px; border-radius: 10px; cursor: pointer;
    background: var(--dba-cohort-card); border: 0; box-shadow: inset 0 0 0 1px var(--dba-cohort-line);
  }
  & select:focus-visible { outline: 2px solid var(--dba-cohort-hi); outline-offset: 2px; }
  & .ic { position: absolute; right: 9px; width: 15px; height: 15px; pointer-events: none; color: var(--dba-cohort-mute); }
}
.dba-cohort__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0 10px;
  & > div {
    grid-row: span 3; display: grid; grid-template-rows: subgrid; gap: 2px; padding: 11px 14px; border-radius: 13px;
    background: var(--dba-cohort-card); box-shadow: inset 0 0 0 1px var(--dba-cohort-line);
    animation: dba-cohort-rise .7s var(--dba-cohort-out) both; animation-delay: calc(var(--i, 0) * 60ms);
  }
  & dt { font-size: 11.5px; font-weight: 550; color: var(--dba-cohort-mute); }
  & dd { font: 720 clamp(17px, 2cqi, 23px)/1.15 var(--dba-cohort-sans); letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
  & span { font-size: 11.5px; color: var(--dba-cohort-mute); font-variant-numeric: tabular-nums; }
  & .up { color: var(--dba-cohort-hi); font-weight: 650; }
  & .dn { color: color-mix(in oklch, var(--dba-cohort-pin) 75%, black); font-weight: 650; }
}
.dba-cohort__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; position: relative;
  background: var(--dba-cohort-card); border-radius: 16px; box-shadow: inset 0 0 0 1px var(--dba-cohort-line);
  animation: dba-cohort-rise .8s var(--dba-cohort-out) both; animation-delay: calc(var(--i, 0) * 90ms + 120ms);
}
.dba-cohort__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 13px 16px 8px; flex-wrap: wrap;
  & h3 { font-size: 13px; font-weight: 680; color: var(--dba-cohort-ink); }
}
.dba-cohort__scale {
  display: inline-flex; align-items: center; gap: 6px;
  & small { font: 10.5px var(--dba-cohort-mono); color: var(--dba-cohort-faint); }
  & i { width: 96px; height: 8px; border-radius: 4px; background: linear-gradient(90deg in oklch, var(--dba-cohort-lo), var(--dba-cohort-hi)); }
}
.dba-cohort__heat { grid-area: heat; }
.dba-cohort__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 0 12px 12px; }
.dba-cohort__grid {
  display: grid; gap: 3px; min-width: min-content;
  grid-template-columns: 70px 60px repeat(var(--n), minmax(30px, 1fr));
  & [role="row"] { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: stretch; }
  & .hd { font: 600 10.5px var(--dba-cohort-mono); color: var(--dba-cohort-faint); text-align: center; padding: 2px 0 4px; letter-spacing: .02em; transition: color .15s; }
  & .hd.xc { color: var(--dba-cohort-ink); }
  & .top { position: sticky; top: 0; z-index: 4; background: var(--dba-cohort-card); }
  & .rhc { position: sticky; left: 0; z-index: 2; display: flex; background: var(--dba-cohort-card); }
  & .szc { position: sticky; left: 70px; z-index: 2; background: var(--dba-cohort-card); }
  & .rh {
    flex: 1; display: flex; align-items: center; gap: 6px; padding: 0 6px 0 4px; border-radius: 7px; text-align: left; font-size: 12px; font-weight: 600; white-space: nowrap;
    transition: background-color .15s, color .15s;
  }
  & .rh i { width: 8px; height: 8px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--dba-cohort-line); flex: none; transition: background-color .2s, box-shadow .2s, transform .3s var(--dba-cohort-out); }
  & .rh:hover { background: var(--dba-cohort-soft); }
  & .rh[aria-pressed="true"] i { background: var(--c); box-shadow: none; transform: scale(1.25); }
  & .xr .rh { color: var(--dba-cohort-hi); }
  & .sz {
    position: relative; display: flex; align-items: center; justify-content: flex-end; padding-right: 8px; font: 11.5px var(--dba-cohort-mono); color: var(--dba-cohort-mute); font-variant-numeric: tabular-nums;
    position: sticky; left: 70px; z-index: 2; background: var(--dba-cohort-card);
  }
  & .sz::before { content: ""; position: absolute; left: 2px; right: 4px; bottom: 3px; height: 2px; border-radius: 2px; background: color-mix(in oklch, var(--dba-cohort-hi) 35%, transparent); transform-origin: right; transform: scaleX(var(--w, 0)); }
  & .c {
    height: 26px; display: grid; place-items: center; border-radius: 6px; font: 600 11px var(--dba-cohort-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em;
    background: color-mix(in oklch, var(--dba-cohort-hi) var(--p, 0%), var(--dba-cohort-lo));
    color: var(--dba-cohort-ink); cursor: default; outline-offset: 1px;
    transition: background-color .6s var(--dba-cohort-out), color .3s, box-shadow .15s, scale .25s var(--dba-cohort-out);
  }
  & .c.dk { color: white; }
  & .c.na { background: transparent; box-shadow: inset 0 0 0 1px var(--dba-cohort-soft); }
  & .xr .c:not(.na), & .c.xc:not(.na) { box-shadow: 0 0 0 1px color-mix(in oklch, var(--dba-cohort-ink) 30%, transparent); }
  & .c.hot { scale: 1.12; z-index: 3; box-shadow: 0 0 0 2px var(--dba-cohort-ink), 0 6px 16px -6px color-mix(in oklch, var(--dba-cohort-ink) 60%, transparent); }
  & .launch { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: color-mix(in oklch, var(--dba-cohort-pin) 75%, black); margin: 2px 0; }
  & .launch::after { content: ""; flex: 1; border-top: 1.5px dashed color-mix(in oklch, var(--dba-cohort-pin) 60%, transparent); }
  & .avg { margin-top: 5px; padding-top: 5px; border-top: 1px solid var(--dba-cohort-line); }
  & .avg .rh { font-weight: 700; }
  &.wave .c, &.wave .rh, &.wave .sz { animation: dba-cohort-pop .55s var(--dba-cohort-out) both; animation-delay: calc(var(--i, 0) * 26ms); }
}
.dba-cohort__curve { grid-area: curve; }
.dba-cohort__pins {
  display: flex; gap: 6px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 3px 6px 3px 8px; border-radius: 999px; font-size: 11.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--dba-cohort-line); transition: opacity .2s, scale .3s var(--dba-cohort-out); @starting-style { opacity: 0; scale: .7; } }
  & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & button .ic { width: 12px; height: 12px; color: var(--dba-cohort-faint); }
  & button:hover .ic { color: var(--dba-cohort-ink); }
}
.dba-cohort__cplot { position: relative; flex: 1; min-height: 0; }
.dba-cohort__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible;
  & text { font: 10px var(--dba-cohort-mono); fill: var(--dba-cohort-faint); font-variant-numeric: tabular-nums; }
  & .grid { stroke: var(--dba-cohort-line); }
  & .band { fill: color-mix(in oklch, var(--dba-cohort-hi) 13%, transparent); }
  & .avgl { fill: none; stroke: var(--dba-cohort-ink); stroke-width: 2.25; stroke-linejoin: round; stroke-linecap: round; }
  & .pinl { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
  & .prev { fill: none; stroke: var(--dba-cohort-hi); stroke-width: 1.75; stroke-dasharray: 3 3; }
  & .xh { stroke: var(--dba-cohort-ink); stroke-opacity: .3; }
  & .dot { stroke: var(--dba-cohort-card); stroke-width: 2; }
  & .lab { font: 600 10.5px var(--dba-cohort-sans); fill: var(--dba-cohort-ink); }
  &.enter .avgl, &.enter .pinl { stroke-dasharray: var(--len); stroke-dashoffset: var(--len); animation: dba-cohort-draw 1.3s var(--dba-cohort-out) .35s forwards; }
  &.enter .band { animation: dba-cohort-fade .9s ease-out .2s both; }
}
.dba-cohort__hint { padding: 0 16px 12px; font-size: 11.5px; color: var(--dba-cohort-faint); text-wrap: pretty; }
.dba-cohort__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 160px; padding: 9px 11px; border-radius: 11px;
  background: var(--dba-cohort-ink); color: var(--dba-cohort-bg); font-size: 12px; line-height: 1.45;
  box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--dba-cohort-ink) 80%, transparent);
  opacity: 0; transition: opacity .12s;
  & b { display: block; font-weight: 700; }
