  svg.classList.toggle('enter', !!enter && !RM);
  $$('.avgl, .pinl', svg).forEach(function (p) {
    var len = Math.ceil(p.getTotalLength()); p.style.setProperty('--len', len);
    if (enter && onlyPins && p.classList.contains('avgl')) { p.style.strokeDasharray = 'none'; p.style.animation = 'none'; }
  });
  if (enter && onlyPins) $$('.band', svg).forEach(function (b) { b.style.animation = 'none'; });
  cg = { x: x, n: n, L: L, pw: pw };
}
svg.addEventListener('pointermove', function (e) {
  if (!cg) return;
  var r = svg.getBoundingClientRect(), t = Math.round((e.clientX - r.left - cg.L) / cg.pw * (cg.n - 1));
  t = Math.max(0, Math.min(cg.n - 1, t));
  if (!S.hover || S.hover.t !== t || S.hover.r !== 'avg') { S.hover = { r: 'avg', t: t }; renderCurve(false); }
