    [G.pre + a[0] + ' retention', pc(avg[a[0]].v), 'weighted across ' + rows.filter(function (c) { return c.vals[a[0]] != null; }).length + ' cohorts'],
    [G.pre + a[1] + ' retention', avg[a[1]] ? pc(avg[a[1]].v) : '—', avg[a[1]] ? 'range ' + pc(avg[a[1]].mn, 0) + ' to ' + pc(avg[a[1]].mx, 0) : 'not reached'],
    ['Best cohort at ' + G.pre + a[0], best ? G.label(best.c.k) : '—', best ? pc(best.p) + ' ' + (M.money ? 'of revenue' : 'retained') : ''],
    ['Recipe swap effect', eff == null ? '—' : (eff >= 0 ? '+' : '−') + Math.abs(eff).toFixed(1) + ' pts', eff == null ? 'needs more data' : '<span class="' + (eff >= 0 ? 'up' : 'dn') + '">' + G.pre + a[0] + '</span> after vs before launch']
  ];
  if (!kp.children.length) kp.innerHTML = tiles.map(function (t, i) { return '<div style="--i:' + i + '"><dt></dt><dd></dd><span></span></div>'; }).join('');
  tiles.forEach(function (t, i) { var d = kp.children[i]; $('dt', d).textContent = t[0]; $('dd', d).textContent = t[1]; $('span', d).innerHTML = t[2]; });
}

/* -------------------------------------------------------------- controls */
function refresh(rebuild) {
  rows = get(); computeAvg();
  if (rebuild) { S.pins = []; S.pinSlots = {}; }
  renderGrid(rebuild); renderPins(); renderKpis(); renderCurve(true);
}
