});
root.addEventListener('keydown', function (e) { if (e.key === 'Escape') tip.classList.remove('on'); });
var ro = new ResizeObserver(function () {
  if (!root.isConnected) { ro.disconnect(); return; }
  var b = box(svg);
  if (Math.abs(b.width - (+svg.dataset.w || 0)) > 1 || Math.abs(b.height - (+svg.dataset.h || 0)) > 1) renderCurve(!svg.dataset.w);
});
rows = get(); computeAvg();
S.pins = [0, 9]; S.pinSlots = { 0: 0, 9: 1 };
renderGrid(true); renderPins(); renderKpis(); renderCurve(true);
ro.observe($('.dba-cohort__cplot'));

