.dba-channels {
  --dba-channels-bg: oklch(0.205 0.02 165);
  --dba-channels-ink: oklch(0.95 0.018 120);
  --dba-channels-accent: oklch(0.86 0.14 122);
  --dba-channels-warm: oklch(0.74 0.14 38);
  --dba-channels-panel: color-mix(in oklch, var(--dba-channels-bg) 90%, var(--dba-channels-ink));
  --dba-channels-raise: color-mix(in oklch, var(--dba-channels-bg) 82%, var(--dba-channels-ink));
  --dba-channels-line: color-mix(in oklch, var(--dba-channels-ink) 10%, transparent);
  --dba-channels-mute: color-mix(in oklch, var(--dba-channels-ink) 62%, var(--dba-channels-bg));
  --dba-channels-faint: color-mix(in oklch, var(--dba-channels-ink) 38%, var(--dba-channels-bg));
  --dba-channels-k0: oklch(0.8 0.13 145);
  --dba-channels-k1: oklch(0.83 0.12 92);
  --dba-channels-k2: oklch(0.72 0.14 35);
  --dba-channels-k3: oklch(0.8 0.09 205);
  --dba-channels-k4: oklch(0.76 0.11 340);
  --dba-channels-k5: oklch(0.88 0.03 120);
  --dba-channels-k6: oklch(0.7 0.11 255);
  --dba-channels-k7: oklch(0.82 0.11 62);
  --dba-channels-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-channels-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-channels-out: cubic-bezier(.2, .9, .25, 1);
  width: 100%;
  height: var(--dba-channels-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  color: var(--dba-channels-ink);
  background:
    radial-gradient(60% 50% at 0% 0%, color-mix(in oklch, var(--dba-channels-accent) 7%, transparent), transparent),
    var(--dba-channels-bg);
  font: 13px/1.45 var(--dba-channels-sans);
  accent-color: var(--dba-channels-accent);
  scrollbar-color: color-mix(in oklch, var(--dba-channels-ink) 18%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, dl, dd, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dba-channels-accent); outline-offset: 2px; border-radius: 6px; }
  & .ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
}
.dba-channels__shell { height: 100%; display: grid; grid-template-columns: 208px minmax(0, 1fr); }
.dba-channels__side {
  display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; overflow: auto; scrollbar-width: thin;
  border-right: 1px solid var(--dba-channels-line); background: color-mix(in oklch, var(--dba-channels-bg) 90%, black);
}
.dba-channels__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px; font-weight: 700; font-size: 15px; letter-spacing: -.02em; line-height: 1.15;
  & small { display: block; font-weight: 500; font-size: 11.5px; color: var(--dba-channels-mute); letter-spacing: 0; }
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; background: var(--dba-channels-accent); fill: none; stroke: var(--dba-channels-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dba-channels__nav { display: grid; gap: 2px; }
.dba-channels__item {
