  &:hover { background: var(--dba-channels-line); color: var(--dba-channels-ink); }
  &[aria-current="page"] { background: color-mix(in oklch, var(--dba-channels-accent) 14%, transparent); color: var(--dba-channels-ink); font-weight: 600; }
  &[aria-current="page"] .ic { color: var(--dba-channels-accent); }
  &[aria-current="page"] b { background: var(--dba-channels-accent); color: var(--dba-channels-bg); }
}
.dba-channels__goal {
  margin-top: auto; padding: 14px 10px 4px; border-top: 1px solid var(--dba-channels-line); display: grid; justify-items: center; gap: 8px; text-align: center;
  & p { font-size: 11px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--dba-channels-faint); }
  & small { font-size: 11.5px; color: var(--dba-channels-mute); text-wrap: balance; }
}
.dba-channels__ringw {
  width: 108px; aspect-ratio: 1; display: grid; place-items: center;
  & > * { grid-area: 1 / 1; }
  & span { font: 720 22px/1 var(--dba-channels-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
}
.dba-channels__ring {
  width: 100%; height: 100%; border-radius: 50%;
  background: conic-gradient(from -90deg, var(--dba-channels-accent) calc(var(--dba-channels-goal) * 1turn), var(--dba-channels-line) 0);
  mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8px));
  transition: --dba-channels-goal 1.8s var(--dba-channels-out);
}
.dba-channels__main {
  min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 16px 18px;
  display: grid; gap: 10px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto 218px minmax(0, 1fr);
}
.dba-channels__head {
  display: flex; align-items: center; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap;
  & h2 { font-size: clamp(19px, 2.2cqi, 24px); font-weight: 720; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
  & p { color: var(--dba-channels-mute); margin-top: 3px; font-variant-numeric: tabular-nums; }
}
.dba-channels__ctrls { display: flex; gap: 8px; flex-wrap: wrap; }
.dba-channels__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--dba-channels-bg) 80%, black); box-shadow: inset 0 0 0 1px var(--dba-channels-line);
  & button { padding: 5px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dba-channels-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dba-channels-ink); }
  & button[aria-checked="true"] { background: var(--dba-channels-raise); color: var(--dba-channels-ink); }
}
.dba-channels__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0 10px;
  & > div {
    grid-row: span 3; display: grid; grid-template-rows: subgrid; gap: 1px; padding: 10px 14px; border-radius: 13px; position: relative; overflow: hidden;
    background: var(--dba-channels-panel); box-shadow: inset 0 0 0 1px var(--dba-channels-line);
    animation: dba-channels-rise .7s var(--dba-channels-out) both; animation-delay: calc(var(--i, 0) * 60ms);
  }
  & dt { font-size: 11.5px; color: var(--dba-channels-mute); }
  & dd { font: 700 clamp(17px, 2cqi, 22px)/1.15 var(--dba-channels-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & span { font-size: 11.5px; color: var(--dba-channels-faint); font-variant-numeric: tabular-nums; }
  & .up { color: var(--dba-channels-accent); font-weight: 650; }
  & .dn { color: var(--dba-channels-warm); font-weight: 650; }
  & svg { position: absolute; right: 10px; top: 12px; width: 64px; height: 26px; overflow: visible; fill: none; stroke: var(--dba-channels-accent); stroke-width: 1.5; stroke-linejoin: round; opacity: .8; }
}
.dba-channels__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; position: relative;
  background: var(--dba-channels-panel); border-radius: 15px; box-shadow: inset 0 0 0 1px var(--dba-channels-line);
  animation: dba-channels-rise .8s var(--dba-channels-out) both; animation-delay: calc(var(--i, 0) * 80ms + 140ms);
}
.dba-channels__plot { position: relative; flex: 1; min-height: 0; }
.dba-channels__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible;
  & text { font: 10px var(--dba-channels-mono); fill: var(--dba-channels-faint); font-variant-numeric: tabular-nums; }
  & .grid { stroke: var(--dba-channels-line); }
  & .ar { stroke: var(--dba-channels-panel); stroke-width: 1; stroke-opacity: .7; transition: opacity .25s; }
  & .ar.dim { opacity: .25; }
  & .xh { stroke: var(--dba-channels-ink); stroke-opacity: .45; stroke-dasharray: 2 3; }
  & .dot { stroke: var(--dba-channels-panel); stroke-width: 1.5; }
  &.enter .areas { animation: dba-channels-wipe 1.3s var(--dba-channels-out) .3s both; }
}
.dba-channels__tbl { min-height: 220px; }
.dba-channels__mix {
  display: flex; gap: 2px; height: 10px; margin: 12px 14px 8px; border-radius: 6px; overflow: hidden; flex: none;
  & button { position: relative; flex: var(--f) 1 0; min-width: 3px; background: var(--c); transition: flex-grow .7s var(--dba-channels-out), opacity .2s, filter .2s; }
  & button[aria-pressed="false"] { opacity: .22; }
  & button:hover { filter: brightness(1.15); }
}
.dba-channels__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; }
.dba-channels__scroll table {
  width: 100%; min-width: 640px; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 2; background: var(--dba-channels-panel); text-align: right; padding: 6px 14px; font-size: 11px; font-weight: 600; color: var(--dba-channels-faint); border-bottom: 1px solid var(--dba-channels-line); white-space: nowrap; }
