  & .dba-channels__c0 { text-align: left; position: sticky; left: 0; z-index: 3; }
  & td { padding: 7px 14px; text-align: right; border-bottom: 1px solid var(--dba-channels-line); white-space: nowrap; font: 12.5px var(--dba-channels-mono); }
  & td:first-child { text-align: left; font: 550 13px var(--dba-channels-sans); position: sticky; left: 0; z-index: 1; background: var(--dba-channels-panel); }
  & tbody tr { transition: background-color .15s, opacity .25s; cursor: pointer; }
  & tbody tr:hover td { background: color-mix(in oklch, var(--dba-channels-panel) 92%, var(--dba-channels-ink)); }
  & tbody tr:has(input:not(:checked)) { opacity: .5; }
  & tbody tr.hide { display: none; }
  & label { display: flex; align-items: center; gap: 10px; cursor: pointer; }
  & input { width: 15px; height: 15px; margin: 0; cursor: pointer; accent-color: var(--c); }
  & .sw { width: 8px; height: 8px; border-radius: 2px; background: var(--c); flex: none; }
  & .sp { display: inline-flex; align-items: center; gap: 10px; }
  & .sp svg { width: 70px; height: 20px; overflow: visible; fill: none; stroke: var(--c); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
  & .sp svg path { stroke-dasharray: 200; stroke-dashoffset: 0; animation: dba-channels-trace 1.4s var(--dba-channels-out) both; animation-delay: calc(var(--i, 0) * 70ms + 300ms); }
  & .up { color: var(--dba-channels-accent); }
  & .dn { color: var(--dba-channels-warm); }
  & .na { color: var(--dba-channels-faint); }
  & tfoot td { position: sticky; bottom: 0; background: color-mix(in oklch, var(--dba-channels-panel) 85%, black); font-weight: 700; border-bottom: 0; border-top: 1px solid var(--dba-channels-line); }
}
@supports (animation-timeline: scroll()) {
  .dba-channels__scroll th { animation: dba-channels-shade linear both; animation-timeline: scroll(nearest block); animation-range: 0 48px; }
}
.dba-channels__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 190px; padding: 10px 12px; border-radius: 12px; font-size: 12px; line-height: 1.5;
  background: color-mix(in oklch, var(--dba-channels-bg) 70%, black); border: 1px solid var(--dba-channels-line);
  box-shadow: 0 16px 40px -14px black; opacity: 0; transition: opacity .12s;
  & b { display: block; font-weight: 700; margin-bottom: 3px; }
  & div { display: grid; grid-template-columns: 8px 1fr auto auto; gap: 8px; align-items: center; font-variant-numeric: tabular-nums; }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & em { font-style: normal; color: var(--dba-channels-faint); font: 11px var(--dba-channels-mono); }
  & strong { font: 600 12px var(--dba-channels-mono); }
  & .tot { border-top: 1px solid var(--dba-channels-line); margin-top: 4px; padding-top: 4px; }
  &.on { opacity: 1; }
}
@property --dba-channels-goal { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dba-channels-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dba-channels-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dba-channels-trace { from { stroke-dashoffset: 200; } }
@keyframes dba-channels-shade { to { box-shadow: 0 8px 14px -10px black; } }

@container (width < 960px) {
  .dba-channels__shell { grid-template-columns: 64px minmax(0, 1fr); }
  .dba-channels__side { padding: 18px 10px; align-items: center; }
  .dba-channels__lbl { display: none; }
  .dba-channels__brand { padding: 0 0 14px; }
  .dba-channels__item { grid-template-columns: 17px; padding: 10px; }
  .dba-channels__main { grid-template-rows: auto auto 220px minmax(320px, 1fr); }
  .dba-channels__kpis svg { display: none; }
}
@container (width < 760px) {
  .dba-channels__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dba-channels__side { flex-direction: row; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--dba-channels-line); overflow-x: auto; overflow-y: hidden; }
  .dba-channels__brand { padding: 0 6px 0 0; }
  .dba-channels__nav { display: flex; gap: 4px; }
  .dba-channels__main { padding: 12px; grid-template-rows: max-content max-content 220px 400px; }
  .dba-channels__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dba-channels__kpis svg { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  .dba-channels__kpis > div, .dba-channels__panel, .dba-channels__svg.enter .areas, .dba-channels__scroll .sp svg path { animation: none; }
  .dba-channels__ring { transition: none; }
  .dba-channels__mix button { transition: none; }
}

