.dba-content {
  --dba-content-paper: oklch(0.968 0.013 88);
  --dba-content-ink: oklch(0.21 0.012 60);
  --dba-content-red: oklch(0.59 0.2 31);
  --dba-content-blue: oklch(0.5 0.08 245);
  --dba-content-sheet: color-mix(in oklch, var(--dba-content-paper) 50%, white);
  --dba-content-rule: color-mix(in oklch, var(--dba-content-ink) 14%, transparent);
  --dba-content-hair: color-mix(in oklch, var(--dba-content-ink) 8%, transparent);
  --dba-content-mute: color-mix(in oklch, var(--dba-content-ink) 60%, var(--dba-content-paper));
  --dba-content-faint: color-mix(in oklch, var(--dba-content-ink) 40%, var(--dba-content-paper));
  --dba-content-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;
  --dba-content-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-content-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-content-out: cubic-bezier(.19, 1, .22, 1);
  width: 100%;
  height: var(--dba-content-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dba-content-paper); color: var(--dba-content-ink);
  font: 13px/1.45 var(--dba-content-sans);
  accent-color: var(--dba-content-red);
  scrollbar-color: color-mix(in oklch, var(--dba-content-ink) 22%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dba-content-rule);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dba-content-red); outline-offset: 2px; }
  & .ic { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
}
.dba-content__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); }
.dba-content__side { display: flex; flex-direction: column; gap: 4px; padding: 18px 12px 16px; min-height: 0; overflow: auto; scrollbar-width: thin; border-right: 3px double var(--dba-content-rule); }
.dba-content__mast {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px; margin-bottom: 6px; border-bottom: 1px solid var(--dba-content-rule);
  font: 700 15px/1.05 var(--dba-content-serif); letter-spacing: -.01em;
  & b { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: var(--dba-content-ink); color: var(--dba-content-paper); font: italic 700 20px var(--dba-content-serif); flex: none; }
}
.dba-content__cap { margin: 8px 8px 4px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--dba-content-faint); }
.dba-content__nav { display: grid; gap: 1px; }
.dba-content__item {
  display: grid; grid-template-columns: 16px 1fr auto; gap: 10px; align-items: center; padding: 8px 9px; border-radius: 8px; text-align: left; color: var(--dba-content-mute);
  transition: background-color .2s, color .2s;
  & b { font: 500 11px var(--dba-content-mono); color: var(--dba-content-faint); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--dba-content-hair); color: var(--dba-content-ink); }
  &[aria-current="page"] { color: var(--dba-content-ink); font-weight: 650; background: var(--dba-content-sheet); box-shadow: inset 2px 0 0 var(--dba-content-red), 0 1px 0 var(--dba-content-rule); }
  &[aria-current="page"] .ic { color: var(--dba-content-red); }
}
.dba-content__colophon { margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dba-content-rule); font: italic 12px/1.45 var(--dba-content-serif); color: var(--dba-content-mute); text-wrap: pretty; }
.dba-content__main {
  min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 16px 18px;
  display: grid; gap: 12px 16px;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head" "list detail";
}
.dba-content__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; padding-bottom: 10px; border-bottom: 2px solid var(--dba-content-ink);
  & h2 { font: 700 clamp(22px, 2.6cqi, 30px)/1 var(--dba-content-serif); letter-spacing: -.02em; text-wrap: balance; }
  & p { margin-top: 6px; color: var(--dba-content-mute); font-variant-numeric: tabular-nums; }
}
.dba-content__ctrls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.dba-content__search {
  display: flex; align-items: center; gap: 7px; padding: 0 10px; height: 34px; border-radius: 9px; background: var(--dba-content-sheet); box-shadow: inset 0 0 0 1px var(--dba-content-rule);
  color: var(--dba-content-faint); transition: box-shadow .2s;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--dba-content-ink); color: var(--dba-content-ink); }
  & input { border: 0; outline: 0; background: none; font: 13px var(--dba-content-sans); color: var(--dba-content-ink); width: 170px; }
  & input::placeholder { color: var(--dba-content-faint); }
}
.dba-content__seg {
  display: inline-flex; padding: 3px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--dba-content-rule);
  & button { padding: 5px 10px; border-radius: 6px; font-size: 12.5px; font-weight: 600; color: var(--dba-content-mute); transition: background-color .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--dba-content-ink); color: var(--dba-content-paper); }
}
.dba-content__list { grid-area: list; min-width: 0; min-height: 0; display: flex; flex-direction: column; animation: dba-content-rise .8s var(--dba-content-out) both .1s; }
.dba-content__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; }
.dba-content__scroll table {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 2; background: var(--dba-content-paper); padding: 4px 8px 7px; text-align: right; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dba-content-faint); border-bottom: 1px solid var(--dba-content-rule); white-space: nowrap; }
  & th.dba-content__t0 { text-align: left; padding-left: 4px; }
  & th button { display: inline-flex; align-items: center; gap: 3px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dba-content-ink); }
  & .dba-content__sic { width: 11px; height: 11px; opacity: 0; transition: opacity .2s, transform .3s var(--dba-content-out); }
  & th[aria-sort="descending"] .dba-content__sic { opacity: 1; }
  & th[aria-sort="ascending"] .dba-content__sic { opacity: 1; transform: rotate(180deg); }
  & td { padding: 9px 8px; text-align: right; border-bottom: 1px solid var(--dba-content-hair); vertical-align: top; font: 12.5px var(--dba-content-mono); white-space: nowrap; }
  & td:first-child { text-align: left; white-space: normal; padding-left: 4px; font-family: var(--dba-content-sans); }
  & tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dba-content-hair); }
  & tbody tr[aria-selected="true"] { background: var(--dba-content-sheet); box-shadow: inset 3px 0 0 var(--dba-content-red); }
  & .pick { display: block; text-align: left; width: 100%; font: 600 13.5px/1.25 var(--dba-content-serif); letter-spacing: -.01em; text-wrap: balance; color: var(--dba-content-ink); }
  & .pick:hover { text-decoration: underline; text-decoration-color: var(--dba-content-red); text-underline-offset: 3px; }
  & small { display: block; margin-top: 3px; font-size: 11.5px; color: var(--dba-content-mute); }
  & small i { font-style: normal; color: var(--dba-content-red); font-weight: 650; letter-spacing: .04em; text-transform: uppercase; font-size: 10px; margin-right: 6px; }
  & .bar { display: flex; gap: 1px; height: 18px; align-items: flex-end; width: 64px; margin-left: auto; }
  & .bar i { flex: 1; height: calc(var(--v) * 100%); background: color-mix(in oklch, var(--dba-content-red) calc(30% + var(--v) * 60%), var(--dba-content-paper)); border-radius: 1px; }
  & .fin { display: inline-flex; align-items: center; gap: 6px; }
  & .fin u { width: 30px; height: 4px; border-radius: 2px; background: var(--dba-content-hair); position: relative; overflow: hidden; text-decoration: none; }
  & .fin u::after { content: ""; position: absolute; inset: 0; background: var(--dba-content-ink); transform-origin: left; transform: scaleX(var(--f)); }
}
@supports (animation-timeline: view()) {
  .dba-content__scroll tbody tr { animation: dba-content-enter linear both; animation-timeline: view(block); animation-range: entry 0% entry 90%; }
}
.dba-content__empty { padding: 30px 8px; font: italic 14px var(--dba-content-serif); color: var(--dba-content-mute); text-align: center; }
.dba-content__detail {
  grid-area: detail; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 10px; overflow: hidden;
  padding: 14px 16px 12px; border-radius: 4px; background: var(--dba-content-sheet);
  box-shadow: 0 0 0 1px var(--dba-content-rule), 0 24px 40px -30px color-mix(in oklch, var(--dba-content-ink) 70%, transparent);
  animation: dba-content-rise .8s var(--dba-content-out) both .2s;
}
.dba-content__kicker { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--dba-content-red); }
.dba-content__hl { font: 700 clamp(18px, 2cqi, 23px)/1.12 var(--dba-content-serif); letter-spacing: -.015em; text-wrap: balance; margin-top: -4px; }
.dba-content__by { font: italic 12.5px var(--dba-content-serif); color: var(--dba-content-mute); margin-top: -4px; }
.dba-content__stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-block: 1px solid var(--dba-content-rule);
  & div { padding: 7px 8px 6px; border-left: 1px solid var(--dba-content-hair); }
  & div:first-child { border-left: 0; padding-left: 0; }
  & dt { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dba-content-faint); }
  & dd { font: 650 16px/1.3 var(--dba-content-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
}
.dba-content__depth { flex: 1; min-height: 120px; display: grid; grid-template-columns: 132px minmax(0, 1fr); gap: 0 12px; position: relative; padding-bottom: 16px; }
.dba-content__mini, .dba-content__curve { position: relative; min-height: 0; }
