  & .hd { fill: var(--dba-content-ink); }
  & .im { fill: color-mix(in oklch, var(--dba-content-blue) 22%, var(--dba-content-sheet)); }
  & .imk { fill: color-mix(in oklch, var(--dba-content-blue) 45%, var(--dba-content-sheet)); }
  & .qt { fill: var(--dba-content-red); }
