}
.dba-content__curve {
  & text { font: 10px var(--dba-content-mono); fill: var(--dba-content-faint); font-variant-numeric: tabular-nums; }
  & .grid { stroke: var(--dba-content-hair); }
  & .ar { fill: color-mix(in oklch, var(--dba-content-red) 16%, transparent); }
  & .ln { fill: none; stroke: var(--dba-content-red); stroke-width: 2; stroke-linejoin: round; }
  & .avg { fill: none; stroke: var(--dba-content-ink); stroke-width: 1.25; stroke-dasharray: 3 3; opacity: .55; }
  & .sec { font: 600 10.5px var(--dba-content-sans); fill: var(--dba-content-mute); }
  & .worst { fill: var(--dba-content-red); font-weight: 700; }
  &.enter .reveal { animation: dba-content-pour 1.4s var(--dba-content-out) .35s both; }
}
.dba-content__xh { position: absolute; left: 0; right: 0; top: 0; height: 0; border-top: 1.5px solid var(--dba-content-ink); pointer-events: none; opacity: 0; transition: opacity .15s; }
.dba-content__xh.on { opacity: .7; }
.dba-content__insight { font: 13px/1.45 var(--dba-content-serif); color: var(--dba-content-mute); text-wrap: pretty; border-left: 2px solid var(--dba-content-red); padding-left: 10px; & b { color: var(--dba-content-ink); } }
.dba-content__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; max-width: 240px; padding: 9px 11px; border-radius: 6px;
  background: var(--dba-content-ink); color: var(--dba-content-paper); font-size: 12px; line-height: 1.45;
  box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--dba-content-ink) 90%, transparent); opacity: 0; transition: opacity .12s;
  & big { display: block; font: 700 18px var(--dba-content-mono); letter-spacing: -.03em; }
  & span { display: block; color: color-mix(in oklch, var(--dba-content-paper) 72%, transparent); }
  & i { font: italic 13px var(--dba-content-serif); color: var(--dba-content-paper); }
  &.on { opacity: 1; }
}
@keyframes dba-content-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dba-content-ink { from { opacity: 0; transform: translateX(-4px); } }
@keyframes dba-content-pour { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dba-content-enter { from { opacity: 0; transform: translateY(14px); } }

@container (width < 960px) {
  .dba-content__shell { grid-template-columns: 62px minmax(0, 1fr); }
  .dba-content__side { padding: 16px 9px; align-items: center; }
  .dba-content__lbl { display: none; }
  .dba-content__mast { padding: 0 0 12px; }
  .dba-content__item { grid-template-columns: 16px; padding: 10px; }
}
@container (width < 880px) {
  .dba-content__main { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 330px 560px; grid-template-areas: "head" "list" "detail"; }
}
@container (width < 760px) {
  .dba-content__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dba-content__side { flex-direction: row; padding: 10px 12px; border-right: 0; border-bottom: 3px double var(--dba-content-rule); overflow-x: auto; overflow-y: hidden; }
  .dba-content__mast { padding: 0 8px 0 0; margin: 0; border: 0; }
  .dba-content__nav { display: flex; gap: 4px; }
  .dba-content__main { padding: 12px; grid-template-rows: max-content 320px 560px; }
  .dba-content__search input { width: 120px; }
}
@container (width < 520px) {
  .dba-content__hm { display: none; }
  .dba-content__stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dba-content__stats div:nth-child(3) { border-left: 0; padding-left: 0; }
  .dba-content__depth { grid-template-columns: 96px minmax(0, 1fr); }
}
