.dba-abtest {
  --dba-abtest-bg: oklch(0.175 0.006 255);
  --dba-abtest-ink: oklch(0.95 0.006 255);
  --dba-abtest-win: oklch(0.85 0.17 132);
  --dba-abtest-lose: oklch(0.7 0.17 24);
  --dba-abtest-hold: oklch(0.83 0.08 82);
  --dba-abtest-v0: color-mix(in oklch, var(--dba-abtest-ink) 70%, var(--dba-abtest-bg));
  --dba-abtest-v1: var(--dba-abtest-win);
  --dba-abtest-v2: oklch(0.78 0.11 215);
  --dba-abtest-panel: color-mix(in oklch, var(--dba-abtest-bg) 93%, var(--dba-abtest-ink));
  --dba-abtest-raise: color-mix(in oklch, var(--dba-abtest-bg) 85%, var(--dba-abtest-ink));
  --dba-abtest-line: color-mix(in oklch, var(--dba-abtest-ink) 9%, transparent);
  --dba-abtest-mute: color-mix(in oklch, var(--dba-abtest-ink) 60%, var(--dba-abtest-bg));
  --dba-abtest-faint: color-mix(in oklch, var(--dba-abtest-ink) 36%, var(--dba-abtest-bg));
  --dba-abtest-tone: var(--dba-abtest-hold);
  --dba-abtest-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-abtest-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-abtest-out: cubic-bezier(.16, 1, .3, 1);
  width: 100%;
  height: var(--dba-abtest-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  color: var(--dba-abtest-ink);
  background:
    linear-gradient(var(--dba-abtest-line) 1px, transparent 1px) 0 0 / 100% 28px,
    linear-gradient(90deg, var(--dba-abtest-line) 1px, transparent 1px) 0 0 / 28px 100%,
    var(--dba-abtest-bg);
  font: 13px/1.45 var(--dba-abtest-sans);
  accent-color: var(--dba-abtest-win);
  scrollbar-color: color-mix(in oklch, var(--dba-abtest-ink) 18%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, table) { margin: 0; padding: 0; }
