.dba-journey {
  --dba-journey-bg: oklch(0.205 0.022 215);
  --dba-journey-ink: oklch(0.95 0.012 200);
  --dba-journey-win: oklch(0.86 0.13 168);
  --dba-journey-lose: oklch(0.56 0.025 215);
  --dba-journey-n0: oklch(0.8 0.1 72);
  --dba-journey-n1: oklch(0.74 0.12 28);
  --dba-journey-n2: oklch(0.79 0.09 248);
  --dba-journey-n3: oklch(0.81 0.1 128);
  --dba-journey-n4: oklch(0.78 0.1 335);
  --dba-journey-n5: oklch(0.83 0.08 205);
  --dba-journey-panel: color-mix(in oklch, var(--dba-journey-bg) 91%, var(--dba-journey-ink));
  --dba-journey-raise: color-mix(in oklch, var(--dba-journey-bg) 83%, var(--dba-journey-ink));
  --dba-journey-line: color-mix(in oklch, var(--dba-journey-ink) 10%, transparent);
  --dba-journey-mute: color-mix(in oklch, var(--dba-journey-ink) 62%, var(--dba-journey-bg));
  --dba-journey-faint: color-mix(in oklch, var(--dba-journey-ink) 38%, var(--dba-journey-bg));
  --dba-journey-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-journey-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-journey-out: cubic-bezier(.22, 1, .36, 1);
  width: 100%;
  height: var(--dba-journey-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  color: var(--dba-journey-ink);
  background: radial-gradient(70% 60% at 100% 100%, color-mix(in oklch, var(--dba-journey-win) 7%, transparent), transparent), var(--dba-journey-bg);
  font: 13px/1.45 var(--dba-journey-sans);
  accent-color: var(--dba-journey-win);
  scrollbar-color: color-mix(in oklch, var(--dba-journey-ink) 18%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dba-journey-win); outline-offset: 2px; border-radius: 6px; }
  & .ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  &.is-off * { animation-play-state: paused !important; }
}
.dba-journey__shell { height: 100%; display: grid; grid-template-columns: 210px minmax(0, 1fr); }
.dba-journey__side { display: flex; flex-direction: column; gap: 4px; padding: 18px 12px; min-height: 0; overflow: auto; scrollbar-width: thin; border-right: 1px solid var(--dba-journey-line); background: color-mix(in oklch, var(--dba-journey-bg) 92%, black); }
.dba-journey__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px; font-weight: 700; font-size: 15px; letter-spacing: -.02em; line-height: 1.15;
  & .ic { width: 30px; height: 30px; padding: 6px; border-radius: 9px; color: var(--dba-journey-bg); background: linear-gradient(135deg in oklch, var(--dba-journey-n0), var(--dba-journey-win)); }
  & small { display: block; font-weight: 500; font-size: 11.5px; color: var(--dba-journey-mute); letter-spacing: 0; }
}
.dba-journey__nav { display: grid; gap: 2px; }
.dba-journey__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; text-align: left; color: var(--dba-journey-mute); transition: background-color .2s, color .2s;
  & small { display: block; font-size: 11px; color: var(--dba-journey-faint); }
  &:hover { background: var(--dba-journey-line); color: var(--dba-journey-ink); }
  &[aria-current="page"] { background: var(--dba-journey-raise); color: var(--dba-journey-ink); font-weight: 600; }
  &[aria-current="page"] .ic { color: var(--dba-journey-win); }
}
.dba-journey__key {
  margin-top: auto; display: grid; gap: 6px; padding: 12px 8px 0; border-top: 1px solid var(--dba-journey-line); font-size: 12px; color: var(--dba-journey-mute);
  & p { display: flex; align-items: center; gap: 8px; }
  & i { width: 10px; height: 10px; border-radius: 3px; }
  & .w { background: var(--dba-journey-win); }
  & .l { background: var(--dba-journey-lose); }
  & .m { background: linear-gradient(90deg in oklch, var(--dba-journey-n0), var(--dba-journey-n2), var(--dba-journey-n4)); }
}
.dba-journey__main {
  min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 16px 18px;
  display: grid; gap: 10px;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) 196px;
  grid-template-areas: "head head" "flow flow" "paths sum";
}
.dba-journey__head {
  grid-area: head; display: flex; align-items: center; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap;
  & h2 { font-size: clamp(19px, 2.2cqi, 24px); font-weight: 720; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
  & p { color: var(--dba-journey-mute); margin-top: 3px; font-variant-numeric: tabular-nums; }
}
.dba-journey__ctrls { display: flex; gap: 8px; flex-wrap: wrap; }
.dba-journey__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--dba-journey-bg) 80%, black); box-shadow: inset 0 0 0 1px var(--dba-journey-line);
  & button { display: inline-flex; align-items: center; padding: 5px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dba-journey-mute); transition: background-color .2s, color .2s; }
  & button .ic { width: 15px; height: 15px; }
  & button:hover { color: var(--dba-journey-ink); }
  & button[aria-checked="true"] { background: var(--dba-journey-raise); color: var(--dba-journey-ink); }
}
.dba-journey__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; overflow: hidden; position: relative;
  background: var(--dba-journey-panel); border-radius: 15px; box-shadow: inset 0 0 0 1px var(--dba-journey-line);
  animation: dba-journey-rise .8s var(--dba-journey-out) both; animation-delay: calc(var(--i, 0) * 80ms + 60ms);
}
.dba-journey__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 14px 4px;
  & h3 { font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dba-journey-mute); }
}
.dba-journey__hint { font-size: 11px; color: var(--dba-journey-faint); }
.dba-journey__flow { grid-area: flow; }
.dba-journey__scroll { position: relative; flex: 1; min-height: 0; overflow-x: auto; overflow-y: hidden; scrollbar-width: thin; }
.dba-journey__svg {
  display: block; height: 100%; min-width: 100%; overflow: visible;
  & .lk { fill: none; stroke-opacity: .5; transition: stroke-opacity .25s, opacity .25s; }
  & .lk:hover { stroke-opacity: .85; }
  &.dim .lk { stroke-opacity: .08; }
  &.dim .lk.on { stroke-opacity: .2; }
  & .tr { fill: none; stroke-opacity: .92; pointer-events: none; }
  & .ants { fill: none; stroke: var(--dba-journey-ink); stroke-opacity: .55; stroke-dasharray: 2 10; stroke-linecap: round; pointer-events: none; animation: dba-journey-march 1.1s linear infinite; }
  & .st { font: 650 10.5px var(--dba-journey-sans); letter-spacing: .09em; fill: var(--dba-journey-faint); }
  & .nd { cursor: pointer; outline: none; }
  & .nd rect { rx: 3px; transition: opacity .25s, filter .2s; }
  & .nd:hover rect, & .nd:focus-visible rect { filter: brightness(1.2); }
  & .nd:focus-visible .ring { opacity: 1; }
  & .ring { fill: none; stroke: var(--dba-journey-win); stroke-width: 2; opacity: 0; }
  &.dim .nd:not(.on) rect { opacity: .3; }
  & .nl { font: 600 11.5px var(--dba-journey-sans); fill: var(--dba-journey-ink); paint-order: stroke; stroke: var(--dba-journey-panel); stroke-width: 4px; stroke-linejoin: round; pointer-events: none; }
  & .nv { font: 500 10.5px var(--dba-journey-mono); fill: var(--dba-journey-mute); paint-order: stroke; stroke: var(--dba-journey-panel); stroke-width: 4px; stroke-linejoin: round; pointer-events: none; font-variant-numeric: tabular-nums; }
  &.dim .nd:not(.on) + .lab { opacity: .35; }
  &.enter .lk { stroke-dasharray: var(--len) var(--len); stroke-dashoffset: var(--len); animation: dba-journey-pour 1.1s var(--dba-journey-out) both; animation-delay: calc(var(--c) * 260ms + 200ms); }
  &.enter .nd rect { transform-box: fill-box; transform-origin: 50% 0; animation: dba-journey-grow .7s var(--dba-journey-out) both; animation-delay: calc(var(--c) * 260ms); }
  &.enter .lab { animation: dba-journey-fade .6s ease-out both; animation-delay: calc(var(--c) * 260ms + 300ms); }
}
.dba-journey__clear {
  position: absolute; right: 12px; bottom: 10px; display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px 5px 8px; border-radius: 999px;
  background: var(--dba-journey-win); color: var(--dba-journey-bg); font-size: 12px; font-weight: 650;
  transition: opacity .2s, scale .3s var(--dba-journey-out); @starting-style { opacity: 0; scale: .8; }
  & .ic { width: 13px; height: 13px; }
  &[hidden] { display: none; }
}
.dba-journey__paths { grid-area: paths; }
.dba-journey__plist {
  list-style: none; flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 2px 8px 8px; display: grid; align-content: start; gap: 2px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto 46px; gap: 10px; align-items: center; padding: 6px 8px; border-radius: 9px; cursor: pointer; transition: background-color .15s; }
  & li:hover { background: var(--dba-journey-line); }
  & li[aria-selected="true"] { background: var(--dba-journey-raise); box-shadow: inset 2px 0 0 var(--dba-journey-win); }
  & .seq { display: flex; align-items: center; gap: 3px; flex-wrap: wrap; min-width: 0; }
  & .seq span { padding: 1px 7px; border-radius: 6px; font-size: 11.5px; background: color-mix(in oklch, var(--c) 18%, transparent); color: color-mix(in oklch, var(--c) 70%, var(--dba-journey-ink)); white-space: nowrap; }
  & .seq .ic { width: 11px; height: 11px; color: var(--dba-journey-faint); }
  & b { font: 600 12px var(--dba-journey-mono); font-variant-numeric: tabular-nums; }
  & em { font: 11px var(--dba-journey-mono); font-style: normal; color: var(--dba-journey-faint); text-align: right; font-variant-numeric: tabular-nums; }
}
.dba-journey__sum { grid-area: sum; padding: 12px 14px; gap: 10px; overflow: auto; scrollbar-width: thin; }
.dba-journey__stats {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 0;
  & div { padding: 8px 10px; border-radius: 10px; background: color-mix(in oklch, var(--dba-journey-bg) 70%, transparent); }
  & dt { font-size: 11px; color: var(--dba-journey-mute); }
  & dd { margin: 0; font: 700 18px/1.25 var(--dba-journey-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & dd small { font: 500 11px var(--dba-journey-mono); color: var(--dba-journey-win); margin-left: 4px; letter-spacing: 0; }
}
.dba-journey__leak { font-size: 12.5px; color: var(--dba-journey-mute); text-wrap: pretty; & b { color: var(--dba-journey-ink); } & em { font-style: normal; color: var(--dba-journey-n1); font-weight: 650; } }
.dba-journey__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 180px; max-width: 260px; padding: 9px 11px; border-radius: 10px; font-size: 12px; line-height: 1.5;
  background: color-mix(in oklch, var(--dba-journey-bg) 70%, black); border: 1px solid var(--dba-journey-line); box-shadow: 0 16px 40px -16px black;
  opacity: 0; transition: opacity .12s;
  & b { display: block; font-weight: 700; }
  & span { display: flex; justify-content: space-between; gap: 12px; color: var(--dba-journey-mute); font-variant-numeric: tabular-nums; }
  & span em { font-style: normal; font-family: var(--dba-journey-mono); color: var(--dba-journey-ink); }
  &.on { opacity: 1; }
}
@keyframes dba-journey-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dba-journey-fade { from { opacity: 0; } }
@keyframes dba-journey-grow { from { transform: scaleY(0); } }
@keyframes dba-journey-pour { to { stroke-dashoffset: 0; } }
@keyframes dba-journey-march { to { stroke-dashoffset: -24; } }

@container (width < 960px) {
  .dba-journey__shell { grid-template-columns: 64px minmax(0, 1fr); }
  .dba-journey__side { padding: 18px 10px; align-items: center; }
  .dba-journey__lbl { display: none; }
  .dba-journey__brand { padding: 0 0 14px; }
  .dba-journey__item { padding: 10px; }
}
@container (width < 820px) {
  .dba-journey__main { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 420px 260px auto; grid-template-areas: "head" "flow" "paths" "sum"; }
  .dba-journey__sum { overflow: visible; }
}
@container (width < 760px) {
  .dba-journey__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dba-journey__side { flex-direction: row; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--dba-journey-line); overflow-x: auto; overflow-y: hidden; }
  .dba-journey__brand { padding: 0 6px 0 0; }
  .dba-journey__nav { display: flex; gap: 4px; }
  .dba-journey__main { padding: 12px; grid-template-rows: max-content 400px 280px max-content; }
  .dba-journey__svg { min-width: 640px; }
}
@media (prefers-reduced-motion: reduce) {
  .dba-journey__panel, .dba-journey__svg.enter :is(.lk, .nd rect, .lab), .dba-journey__svg .ants { animation: none; }
  .dba-journey__svg.enter .lk { stroke-dasharray: none; }
  .dba-journey__svg .ants { display: none; }
  .dba-journey__clear { transition: none; }
}

