css:
.dba-mobile {
  --dba-mobile-bg: oklch(0.975 0.004 255);
  --dba-mobile-ink: oklch(0.23 0.02 262);
  --dba-mobile-pri: oklch(0.53 0.19 259);
  --dba-mobile-sun: oklch(0.86 0.15 92);
  --dba-mobile-ok: oklch(0.63 0.15 155);
  --dba-mobile-bad: oklch(0.6 0.2 27);
  --dba-mobile-ios: var(--dba-mobile-pri);
  --dba-mobile-and: oklch(0.72 0.15 160);
  --dba-mobile-card: white;
  --dba-mobile-line: color-mix(in oklch, var(--dba-mobile-ink) 9%, transparent);
  --dba-mobile-soft: color-mix(in oklch, var(--dba-mobile-ink) 4%, transparent);
  --dba-mobile-mute: color-mix(in oklch, var(--dba-mobile-ink) 60%, var(--dba-mobile-bg));
  --dba-mobile-faint: color-mix(in oklch, var(--dba-mobile-ink) 38%, var(--dba-mobile-bg));
  --dba-mobile-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dba-mobile-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dba-mobile-out: cubic-bezier(.2, .9, .3, 1);
  width: 100%;
  height: var(--dba-mobile-h, 680px);
  container-type: inline-size;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 20px;
  background: var(--dba-mobile-bg); color: var(--dba-mobile-ink);
  font: 13px/1.45 var(--dba-mobile-sans);
  accent-color: var(--dba-mobile-pri);
  scrollbar-color: color-mix(in oklch, var(--dba-mobile-ink) 18%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dba-mobile-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dba-mobile-pri); outline-offset: 2px; border-radius: 8px; }
  & .ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  &.is-off * { animation-play-state: paused !important; }
}
.dba-mobile__shell { height: 100%; display: grid; grid-template-columns: 200px minmax(0, 1fr); }
.dba-mobile__side { display: flex; flex-direction: column; gap: 4px; padding: 18px 12px; min-height: 0; overflow: auto; scrollbar-width: thin; border-right: 1px solid var(--dba-mobile-line); }
.dba-mobile__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px; font-weight: 720; font-size: 15px; letter-spacing: -.02em; line-height: 1.15;
  & small { display: block; font-weight: 500; font-size: 11.5px; color: var(--dba-mobile-mute); letter-spacing: 0; }
}
.dba-mobile__app {
  width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; flex: none;
  background: linear-gradient(160deg in oklch, var(--dba-mobile-and), var(--dba-mobile-pri));
  box-shadow: 0 6px 14px -6px var(--dba-mobile-pri), inset 0 1px 0 color-mix(in oklch, white 40%, transparent);
  & svg { width: 20px; height: 20px; fill: none; stroke: white; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
}
.dba-mobile__nav { display: grid; gap: 2px; }
.dba-mobile__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; color: var(--dba-mobile-mute); text-align: left; transition: background-color .2s, color .2s;
  &:hover { background: var(--dba-mobile-soft); color: var(--dba-mobile-ink); }
  &[aria-current="page"] { background: var(--dba-mobile-card); color: var(--dba-mobile-ink); font-weight: 620; box-shadow: 0 1px 2px var(--dba-mobile-line), 0 6px 18px -12px color-mix(in oklch, var(--dba-mobile-ink) 50%, transparent); }
