  for (var k = 0; k < VNAMES.length; k++) { var st = verStats(k); if (st.sess > 2000 && (!worst || st.cfs < worst.st.cfs)) worst = { k: k, st: st }; }
  card.innerHTML = '<div class="dba-mobile__rc"><div class="top"><h4>Crash budget</h4><span class="dba-mobile__pill" style="--c:' + (u >= 0.99 ? 'var(--dba-mobile-ok)' : 'var(--dba-mobile-bad)') + '"><i></i>' + (u >= 0.99 ? 'Healthy' : 'Over budget') + '</span></div>' +
    '<div class="dba-mobile__gauge" style="--c:' + (u >= 0.992 ? 'var(--dba-mobile-ok)' : u >= 0.99 ? 'var(--dba-mobile-sun)' : 'var(--dba-mobile-bad)') + '"><div class="ring" role="img" aria-label="Crash-free users ' + pc(u, 2) + '"><b>' + pc(u, 2) + '</b></div><dl><div><dt>Crash-free users</dt><dd>' + pc(u, 2) + '</dd></div><div><dt>Crash-free sessions</dt><dd>' + pc(s, 2) + '</dd></div><div><dt>Budget used</dt><dd>' + pc((1 - u) / 0.01, 0) + '</dd></div><div><dt>Worst version</dt><dd>' + VNAMES[worst.k] + '</dd></div></dl></div>' +
    '<p class="notes">' + (S.plat === 'ios' ? 'iOS stayed inside the 99.0% crash-free users SLO for the whole period.' : 'Android 4.2.0 shipped a background sync crash on Sep 22. The rollout was halted at 20% on Sep 26 and 4.2.1 is replacing it.') + '</p></div>';
  var ring = $('.ring', card), sweep = Math.max(0, Math.min(1, 1 - (1 - u) / 0.01));
  requestAnimationFrame(function () { if (!root.isConnected) return; ring.style.setProperty('--dba-mobile-sweep', sweep.toFixed(3)); });
}
function renderIssues(total) {
  var sp = span(), rows = ISSUES.filter(function (i) { return plats().indexOf(i.p) >= 0; }).map(function (is) {
    var daily = [], n = 0;
    for (var t = sp.a; t <= sp.b; t++) { var v = 0; D[is.p][t].crashes.forEach(function (c, k) { v += c * is.w(k); }); daily.push(v); n += v; }
    return { is: is, n: Math.round(n), daily: daily };
  }).sort(function (a, b) { return b.n - a.n; });
  var listed = sum(rows.map(function (r) { return r.n; })), other = Math.max(0, total - listed);
  function spark(a) { var mx = Math.max.apply(null, a) || 1, k = Math.max(1, Math.ceil(a.length / 30)), pts = []; for (var i = 0; i < a.length; i += k) pts.push(a[i]); return '<svg viewBox="0 0 64 18" aria-hidden="true"><path d="M' + pts.map(function (v, i) { return (i / Math.max(1, pts.length - 1) * 64).toFixed(1) + ',' + (17 - v / mx * 15).toFixed(1); }).join('L') + '"/></svg>'; }
  $('.dba-mobile__bottom').innerHTML = '<div class="dba-mobile__scroll"><table><thead><tr><th>Top crashes</th><th>Events</th><th class="hm">Share</th><th class="hm">Trend</th><th>Status</th></tr></thead><tbody>' +
    rows.map(function (r) { return '<tr><td><span class="iss">' + esc(r.is.id) + '<small>' + esc(r.is.where) + ' · ' + PL[r.is.p].name + '</small></span></td><td>' + nf(r.n) + '</td><td class="hm">' + pc(r.n / Math.max(1, total)) + '</td><td class="hm sp" style="--c:' + r.is.c + '">' + spark(r.daily) + '</td><td class="t"><span class="dba-mobile__pill" style="--c:' + r.is.c + '"><i></i>' + r.is.status + '</span></td></tr>'; }).join('') +
    '<tr><td><span class="iss">Other issues<small>' + (S.plat === 'all' ? 41 : S.plat === 'ios' ? 17 : 24) + ' smaller signatures</small></span></td><td>' + nf(other) + '</td><td class="hm">' + pc(other / Math.max(1, total)) + '</td><td class="hm"></td><td></td></tr></tbody></table></div>';
}

/* ------------------------------------------------------------ engagement */
function renderRetention() {
  var R = { ios: [0.46, 0.24, 0.13], android: [0.41, 0.19, 0.1] }, card = $('.dba-mobile__card');
  card.innerHTML = '<div class="dba-mobile__rc"><div class="top"><h4>New user retention</h4></div><div class="dba-mobile__ret">' + ['Day 1', 'Day 7', 'Day 30'].map(function (d, i) {
    return '<div class="row"><b>' + d.replace('Day ', 'D') + '</b><div class="pair">' + plats().map(function (p, k) { return '<span class="bar" style="--c:' + PL[p].c + ';--v:' + R[p][i] + ';--i:' + (i * 2 + k) + '"><i></i>' + pc(R[p][i], 0) + '</span>'; }).join('') + '</div></div>';
  }).join('') + '</div><p class="notes">Installs from Sep 1 to Sep 9, measured on their first 30 days. ' + (S.plat === 'android' ? '' : 'iOS keeps more users because reminders are on by default.') + '</p></div>';
}
function renderScreens(sess) {
  var views = SCREENS.map(function (s) { return { s: s, n: Math.round(sess * 3.4 * s[1]) }; });
  var mx = views[0].n;
  $('.dba-mobile__bottom').innerHTML = '<div class="dba-mobile__scroll"><table><thead><tr><th>Screen</th><th>Views</th><th class="hm">Avg time</th><th>Exit rate</th><th class="hm">Share</th></tr></thead><tbody>' +
    views.map(function (v) { return '<tr><td class="t">' + v.s[0] + '</td><td>' + nf(v.n) + '</td><td class="hm">' + v.s[2] + 's</td><td class="' + (v.s[3] > 0.25 ? 'bad' : '') + '">' + pc(v.s[3], 0) + '</td><td class="hm sp"><svg viewBox="0 0 64 18" aria-hidden="true"><rect x="0" y="5" height="8" rx="2" width="' + (v.n / mx * 64).toFixed(1) + '" style="fill:var(--dba-mobile-pri);stroke:none"/></svg></td></tr>'; }).join('') + '</tbody></table></div>';
}

/* --------------------------------------------------------------- controls */
$$('.dba-mobile__seg').forEach(function (grp) {
  function pick(b) {
    $$('[role="radio"]', grp).forEach(function (x) { var on = x === b; x.setAttribute('aria-checked', on); x.tabIndex = on ? 0 : -1; });
    if (grp.dataset.k === 'plat') S.plat = b.dataset.v; else S.range = +b.dataset.v;
    if (S.plat === 'ios' && S.sel === 6) S.sel = 5;
    morph(function () { renderView(true); }, $('.dba-mobile__main'), 'dba-mobile-main');
  }
  grp.addEventListener('click', function (e) { var b = e.target.closest('[role="radio"]'); if (b && b.getAttribute('aria-checked') !== 'true') pick(b); });
  roving(grp, '[role="radio"]', pick);
});
$('.dba-mobile__nav').addEventListener('click', function (e) {
  var b = e.target.closest('.dba-mobile__item'); if (!b || b.hasAttribute('aria-current')) return;
  $$('.dba-mobile__item').forEach(function (x) { if (x === b) x.setAttribute('aria-current', 'page'); else x.removeAttribute('aria-current'); });
  morph(function () { S.view = b.dataset.v; renderView(true); }, $('.dba-mobile__main'), 'dba-mobile-main');
});
root.addEventListener('keydown', function (e) { if (e.key === 'Escape') tip.classList.remove('on'); });
var io = new IntersectionObserver(function (es) { root.classList.toggle('is-off', !es[es.length - 1].isIntersecting); });
var ro = new ResizeObserver(function () {
  if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
  var b = box(svg);
  if (Math.abs(b.width - (+svg.dataset.w || 0)) > 1 || Math.abs(b.height - (+svg.dataset.h || 0)) > 1) { if (CG) { CG.cfg.enter = !svg.dataset.w; chart(CG.cfg); } else renderView(true); }
});
renderView(true);
io.observe(root);
ro.observe($('.dba-mobile__plot'));
